import { useEffect, useRef, useState } from "react";
import { api, fmtErr, API } from "@/lib/api";
import { Loader2, Upload, FileText, Image as ImageIcon, Trash2, Download } from "lucide-react";

const MAX_BYTES = 10 * 1024 * 1024;
const ALLOWED = ["jpg", "jpeg", "png", "pdf"];

export default function AttachmentsTab({ caseId }) {
  const [files, setFiles] = useState([]);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const inputRef = useRef(null);

  const load = async () => {
    try {
      const { data } = await api.get(`/cases/${caseId}/attachments`);
      setFiles(data.attachments);
    } catch (e) { setErr(fmtErr(e)); }
  };
  useEffect(() => { load(); }, [caseId]);

  const onPick = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    e.target.value = "";
    setErr("");
    const ext = file.name.split(".").pop().toLowerCase();
    if (!ALLOWED.includes(ext)) { setErr("Only JPG, PNG, PDF allowed."); return; }
    if (file.size > MAX_BYTES) { setErr("Max 10MB."); return; }
    setBusy(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      await api.post(`/cases/${caseId}/attachments`, fd, { headers: { "Content-Type": "multipart/form-data" } });
      await load();
    } catch (e2) { setErr(fmtErr(e2)); }
    finally { setBusy(false); }
  };

  const remove = async (f) => {
    if (!window.confirm(`Delete ${f.original_filename}?`)) return;
    try { await api.delete(`/attachments/${f.id}`); load(); }
    catch (e) { setErr(fmtErr(e)); }
  };

  const open = async (f) => {
    try {
      const resp = await api.get(`/attachments/${f.id}/download`, { responseType: "blob" });
      const url = URL.createObjectURL(resp.data);
      window.open(url, "_blank");
      setTimeout(() => URL.revokeObjectURL(url), 60000);
    } catch (e) { setErr(fmtErr(e)); }
  };

  return (
    <div className="bg-white border border-gray-200 rounded-md p-6" data-testid="attachments-tab">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h3 className="font-display text-base font-semibold text-gray-900">Attachments</h3>
          <p className="text-xs text-gray-500 mt-0.5">Lab reports, photos & PDFs. Max 10MB · JPG/PNG/PDF.</p>
        </div>
        <input ref={inputRef} type="file" accept=".jpg,.jpeg,.png,.pdf" className="hidden" onChange={onPick} data-testid="attachment-file-input" />
        <button onClick={() => inputRef.current?.click()} disabled={busy} className="inline-flex items-center gap-2 px-3.5 py-2 bg-teal-700 hover:bg-teal-800 disabled:opacity-60 text-white rounded-md text-sm font-medium" data-testid="upload-attachment-btn">
          {busy ? <Loader2 size={14} className="animate-spin" /> : <Upload size={14} strokeWidth={1.5} />}
          Upload
        </button>
      </div>
      {err && <div className="text-sm text-red-700 bg-red-50 border border-red-200 rounded-md px-3 py-2 mb-4">{err}</div>}
      {files.length === 0 ? (
        <div className="border border-dashed border-gray-200 rounded-md p-10 text-center text-sm text-gray-400">No files yet.</div>
      ) : (
        <div className="divide-y divide-gray-100 border border-gray-200 rounded-md">
          {files.map((f) => (
            <div key={f.id} className="px-4 py-3 flex items-center gap-3" data-testid={`attachment-${f.id}`}>
              <div className="w-9 h-9 rounded-md bg-teal-50 text-teal-700 grid place-items-center">
                {f.content_type?.startsWith("image/") ? <ImageIcon size={16} strokeWidth={1.5} /> : <FileText size={16} strokeWidth={1.5} />}
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-medium text-gray-900 truncate">{f.original_filename}</div>
                <div className="text-xs text-gray-500 tabular-nums">
                  {(f.size_bytes / 1024).toFixed(0)} KB · {new Date(f.created_at).toLocaleString()} · {f.uploaded_by_name}
                </div>
              </div>
              <button onClick={() => open(f)} className="px-2.5 py-1.5 text-xs font-medium border border-gray-200 rounded hover:border-teal-600 inline-flex items-center gap-1" data-testid={`open-${f.id}`}>
                <Download size={12} /> Open
              </button>
              <button onClick={() => remove(f)} className="text-gray-400 hover:text-red-600" data-testid={`delete-${f.id}`}>
                <Trash2 size={14} />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api, fmtErr } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { ArrowRight, Plus, Printer } from "lucide-react";
import { PackageSummary, money, dateLabel } from "./PackageSummary";
import { PackageForm } from "./PackageForm";
import { PackagePaymentForm } from "./PackagePaymentForm";
import { PackageLedger } from "./PackageLedger";

export const PackageBilling = ({ caseData: c, onSaved }) => {
  const [packages, setPackages] = useState([]), [selected, setSelected] = useState(c.package_id || ""), [p, setP] = useState(null);
  const [creating, setCreating] = useState(false), [busy, setBusy] = useState(false), [error, setError] = useState(""), [medicines, setMedicines] = useState(true);
  const load = async () => {
    const r = await api.get("/packages", { params: { patient_id: c.patient_id, page_size: 100 } }); setPackages(r.data.packages);
    if (c.package_id) { const detail = await api.get(`/packages/${c.package_id}`); setP(detail.data.package); }
  };
  useEffect(() => { load().catch(e => setError(fmtErr(e))); }, [c.package_id, c.patient_id]);
  const link = async (packageId = selected) => {
    setBusy(true); setError("");
    try { await api.put(`/cases/${c.id}/package`, { package_id: packageId }); setSelected(packageId); await onSaved(); }
    catch (e) { setError(fmtErr(e)); } finally { setBusy(false); }
  };
  const complete = async () => {
    setBusy(true); setError("");
    try { await api.post(`/cases/${c.id}/package/complete-visit`, { medicines_taken: medicines }); await onSaved(); }
    catch (e) { setError(fmtErr(e)); } finally { setBusy(false); }
  };
  return <section data-testid="package-billing" className="space-y-4">
    {error && <p role="alert" className="text-red-700 text-sm" data-testid="package-billing-error">{error}</p>}
    {!c.package_id && <div className="py-5 border-y border-gray-200 space-y-4"><h2 className="font-display text-lg font-semibold">Allocate this visit</h2><label className="text-sm block">Patient package<select value={selected} onChange={e => setSelected(e.target.value)} className="mt-2 w-full bg-white border rounded-md p-3" data-testid="billing-package-select"><option value="">Select package</option>{packages.filter(x => ["ACTIVE", "ENDING_SOON"].includes(x.package_status)).map(x => <option key={x.id} value={x.id}>{x.treatment_name} · {x.name} · {x.duration_label} · Ends {dateLabel(x.end_date)} · Balance {money(x.outstanding)}</option>)}</select></label><div className="flex flex-wrap gap-2"><Button onClick={() => link()} disabled={!selected || busy} className="bg-teal-700 hover:bg-teal-800" data-testid="link-billing-package">Use this package</Button><Button variant="outline" onClick={() => setCreating(v => !v)} data-testid="billing-new-package"><Plus size={15} />New package</Button><Link to={`/pro/packages?patient_id=${c.patient_id}`} className="text-sm text-teal-700 py-2" data-testid="billing-package-history-link">Package history / renewals</Link></div></div>}
    {creating && <PackageForm patientId={c.patient_id} onCancel={() => setCreating(false)} onSaved={async next => { setCreating(false); await load(); if (["ACTIVE", "ENDING_SOON"].includes(next.package_status)) await link(next.id); }} />}
    {p && <><PackageSummary value={p} prefix="billing-package-summary" /><div className="max-w-2xl"><PackagePaymentForm key={p.id} value={p} caseId={c.id} onSaved={async () => { await load(); await onSaved(); }} /></div>
      <div className="border-y border-gray-200 py-4 flex flex-wrap gap-3 items-center"><label className="text-sm inline-flex items-center gap-2"><input type="checkbox" checked={medicines} onChange={e => setMedicines(e.target.checked)} data-testid="package-visit-medicines" />Medicines for this visit</label><Button disabled={busy || !["AWAITING_PRO_REVIEW", "READY_FOR_BILLING", "PAYMENT_PENDING", "PARTIALLY_PAID"].includes(c.status)} onClick={complete} className="bg-teal-700 hover:bg-teal-800" data-testid="complete-package-visit">{medicines ? "Send to Pharmacy" : "Complete visit"}<ArrowRight size={15} /></Button><Link to={`/pro/cases/${c.id}/receipt`} target="_blank" className="inline-flex items-center gap-2 text-sm text-teal-700" data-testid="package-bill-print"><Printer size={15} />Print bill</Link><Link to={`/pro/packages/${p.id}`} className="text-sm text-teal-700" data-testid="billing-package-detail-link">Full package ledger</Link></div>
      <PackageLedger value={{ ...p, transactions: p.transactions.filter(t => t.case_id === c.id) }} /></>}
  </section>;
};

import { useEffect, useRef, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { api, fmtErr, fmtIST } from "@/lib/api";
import StatusBadge from "@/components/StatusBadge";
import {
  ArrowLeft, Loader2, Sparkles, Save, ArrowRight, Plus, Trash2,
  Stethoscope, Pill, Paperclip, CalendarClock, Brain, Wand2,
} from "lucide-react";
import AttachmentsTab from "@/components/AttachmentsTab";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { ClinicalNotesEditor } from "@/components/ClinicalNotesEditor";
import { PatientPhoto } from "@/components/PatientPhoto";
import { PatientHistoryPanel, usePatientHistory } from "@/components/PatientHistoryPanel";

const TABS = [
  { key: "notes",       label: "Notes",        icon: Stethoscope },
  { key: "rx",          label: "Prescription", icon: Pill },
  { key: "attachments", label: "Attachments",  icon: Paperclip },
  { key: "followup",    label: "Follow-up",    icon: CalendarClock },
  { key: "ai",          label: "AI Assist",    icon: Brain },
];

export default function CaseDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const activeCaseId = useRef(id);
  activeCaseId.current = id;
  const [data, setData] = useState(null);
  const [tab, setTab] = useState("notes");
  const [err, setErr] = useState("");
  const [bypassOpen, setBypassOpen] = useState(false);
  const [bypassReason, setBypassReason] = useState("");
  const [bypassErr, setBypassErr] = useState("");
  const [pendingRxDraft, setPendingRxDraft] = useState(null); // {items, notes_for_patient, token}
  const history = usePatientHistory(data?.case?.id === id ? data.case.patient_id : null, id);

  const reload = async () => {
    try { const r = await api.get(`/cases/${id}`); if (activeCaseId.current === id) setData(r.data); }
    catch (e) { if (activeCaseId.current === id) setErr(fmtErr(e)); }
  };
  useEffect(() => {
    setData(null); setErr(""); setTab("notes"); setPendingRxDraft(null);
    setBypassOpen(false); setBypassReason(""); setBypassErr("");
    reload();
  }, [id]);

  if (err) return <div className="p-8 text-red-700">{err}</div>;
  if (!data || data.case.id !== id) return <div className="p-8 grid place-items-center text-gray-400"><Loader2 className="animate-spin" /></div>;

  const c = data.case;

  const startConsult = async () => {
    await api.patch(`/cases/${c.id}/status`, { status: "IN_CONSULTATION" });
    reload();
  };
  const sendToPro = async () => {
    await api.patch(`/cases/${c.id}/status`, { status: "AWAITING_PRO_REVIEW" });
    reload();
  };
  const submitBypass = async () => {
    if (!bypassReason.trim()) { setBypassErr("Please write a brief reason."); return; }
    try {
      await api.patch(`/cases/${c.id}/status`, { status: "SENT_TO_PHARMACY", bypass_reason: bypassReason.trim() });
      setBypassOpen(false); setBypassReason(""); setBypassErr("");
      reload();
    } catch (e) { setBypassErr(fmtErr(e)); }
  };

  return (
    <div className="p-4 sm:p-6 lg:p-8 max-w-6xl mx-auto" data-testid="doctor-case-detail">
      <button
        onClick={() => navigate(-1)}
        className="inline-flex items-center gap-1 text-sm text-gray-500 hover:text-gray-900 mb-3 min-h-[36px]"
        data-testid="back-to-queue-btn"
      >
        <ArrowLeft size={14} /> Back to queue
      </button>

      {/* Header — stacked on mobile, side-by-side on desktop */}
      <div className="bg-white border border-gray-200 rounded-md p-4 sm:p-6 mb-4 sm:mb-6">
        <div className="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-4">
          <div className="min-w-0">
            <div className="text-xs uppercase tracking-wider text-gray-500 font-semibold mb-1 tabular-nums">{c.case_uid}</div>
            <div className="text-xs text-gray-500 mb-2" data-testid="case-visit-date">{c.is_historical || c.status === "CLOSED" ? "Selected historical visit" : "Current visit"} · {fmtIST(c.created_at)}{history.data?.is_first_visit ? " · First recorded visit in this history" : ""}</div>
            <div className="flex items-center gap-3"><PatientPhoto patientId={c.patient?.id} testId="doctor-patient-photo" /><h1 className="font-display text-2xl sm:text-3xl font-semibold text-gray-900 break-words min-w-0" data-testid="doctor-patient-name">{c.patient?.first_name} {c.patient?.last_name}</h1></div>
            <div className="text-sm text-gray-600 mt-1 tabular-nums">
              {c.patient?.patient_uid} · {c.patient?.gender} · {c.patient?.age}y · {c.patient?.phone}
            </div>
            <div className="text-sm text-gray-700 mt-3">
              <span className="text-xs uppercase tracking-wider font-semibold text-gray-500 mr-2">Complaint:</span>
              {c.complaint_text}
            </div>
          </div>
          <div className="flex flex-col sm:flex-row lg:flex-col items-start lg:items-end gap-3 sm:gap-4 lg:gap-3 shrink-0">
            <div className="flex items-center gap-3">
              <StatusBadge status={c.status} />
              <div className="text-xs text-gray-500">Doctor: <span className="font-medium text-gray-900">{c.doctor?.display_name}</span></div>
            </div>
            <div className="flex flex-wrap gap-2 w-full sm:w-auto">
              {c.status === "WAITING_FOR_DOCTOR" && (
                <button onClick={startConsult} className="px-3 py-2 bg-teal-700 hover:bg-teal-800 text-white rounded-md text-xs sm:text-sm font-medium min-h-[40px]" data-testid="start-consult-btn">Start consultation</button>
              )}
              {(c.status === "IN_CONSULTATION" || c.status === "WAITING_FOR_DOCTOR") && (
                <>
                  <button onClick={sendToPro} className="inline-flex items-center gap-1 px-3 py-2 bg-teal-700 hover:bg-teal-800 text-white rounded-md text-xs sm:text-sm font-medium min-h-[40px]" data-testid="send-pro-btn">
                    Send to PRO <ArrowRight size={12} />
                  </button>
                  <button onClick={() => setBypassOpen(true)} className="inline-flex items-center gap-1 px-3 py-2 bg-white border border-indigo-300 text-indigo-700 hover:bg-indigo-50 rounded-md text-xs sm:text-sm font-medium min-h-[40px]" title="Skip PRO — for known patients / quick refills" data-testid="send-pharmacy-bypass-btn">
                    Direct to Pharmacy
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Tabs — horizontally scrollable strip with icons */}
      <div className="border-b border-gray-200 mb-4 sm:mb-6 -mx-4 sm:mx-0 px-4 sm:px-0 overflow-x-auto no-scrollbar">
        <div className="flex gap-1 min-w-max">
          {TABS.map(({ key, label, icon: Icon }) => (
            <button
              key={key}
              onClick={() => setTab(key)}
              className={`inline-flex items-center gap-1.5 px-3 sm:px-4 py-2.5 text-sm font-medium border-b-2 -mb-px transition-colors whitespace-nowrap min-h-[44px] ${
                tab === key
                  ? "border-teal-700 text-teal-700"
                  : "border-transparent text-gray-500 hover:text-gray-900"
              }`}
              data-testid={`tab-${key}`}
            >
              <Icon size={15} strokeWidth={1.75} />
              {label}
            </button>
          ))}
        </div>
      </div>

      {tab === "notes" && <>
        <PatientHistoryPanel history={history} />
        {history.ready && <ClinicalNotesEditor key={c.id} caseId={c.id} initial={data.clinical_notes} onSaved={reload}
          primaryHistory={history.data?.primary_history} primarySources={history.data?.primary_history_sources} hasPreviousVisits={!!history.data?.total} />}
      </>}
      {tab === "rx"          && (
        <><PatientHistoryPanel history={history} prescriptionOnly /><PrescriptionTab key={c.id}
          caseId={c.id}
          latest={data.latest_prescription}
          draft={pendingRxDraft}
          onDraftConsumed={() => setPendingRxDraft(null)}
          onSaved={reload}
        /></>
      )}
      {tab === "attachments" && <AttachmentsTab caseId={c.id} />}
      {tab === "followup"    && <FollowupTab caseData={c} onSaved={reload} />}
      {tab === "ai"          && (
        <AiTab
          caseId={c.id}
          onApplyDraft={(items, notes_for_patient) => {
            setPendingRxDraft({ items, notes_for_patient, token: Date.now() });
            setTab("rx");
          }}
        />
      )}

      {bypassOpen && (
        <div className="fixed inset-0 bg-black/40 grid place-items-center z-50 p-4" onClick={() => setBypassOpen(false)} data-testid="bypass-modal">
          <div className="bg-white rounded-md shadow-xl border border-gray-200 p-6 w-full max-w-md" onClick={(e) => e.stopPropagation()}>
            <h2 className="font-display text-lg font-semibold text-gray-900 mb-1">Send directly to Pharmacy?</h2>
            <p className="text-sm text-gray-600 mb-4">This skips PRO review (billing). Use only for quick refills or established patients. A short reason is required for the audit log.</p>
            <label className="text-xs uppercase tracking-wider font-semibold text-gray-500 block mb-1.5">Reason</label>
            <input
              type="text"
              autoFocus
              value={bypassReason}
              onChange={(e) => setBypassReason(e.target.value)}
              placeholder="e.g. Refill — known patient, no consult fee"
              className="w-full px-3 py-2.5 border border-gray-300 rounded-md text-sm focus:outline-none focus:border-teal-700 focus:ring-2 focus:ring-teal-700/20"
              data-testid="bypass-reason-input"
            />
            {bypassErr && <div className="text-sm text-red-700 bg-red-50 border border-red-200 rounded mt-3 px-3 py-2">{bypassErr}</div>}
            <div className="flex flex-col-reverse sm:flex-row sm:justify-end gap-2 mt-5">
              <button onClick={() => { setBypassOpen(false); setBypassReason(""); setBypassErr(""); }} className="px-3 py-2 text-sm text-gray-700 hover:bg-gray-100 rounded min-h-[40px]">Cancel</button>
              <button onClick={submitBypass} className="px-3 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-sm font-medium min-h-[40px]" data-testid="bypass-confirm-btn">Send to Pharmacy</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const EMPTY_ITEM = { medicine_name: "", potency: "", dosage: "", frequency: "", duration_days: "", instructions: "" };
const withKey = (it) => ({
  ...it,
  _key: it._key || (typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`),
});

function PrescriptionTab({ caseId, latest, draft, onDraftConsumed, onSaved }) {
  const [items, setItems] = useState(
    latest?.items?.length ? latest.items.map(withKey) : [withKey({ ...EMPTY_ITEM })]
  );
  const [notesForPatient, setNotesForPatient] = useState(latest?.notes_for_patient || "");
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");
  const [draftBanner, setDraftBanner] = useState("");

  // When an AI draft arrives from the AI tab, replace items + notes_for_patient
  useEffect(() => {
    if (draft && Array.isArray(draft.items) && draft.items.length) {
      setItems(draft.items.map((it) => withKey({ ...EMPTY_ITEM, ...it })));
      if (draft.notes_for_patient) setNotesForPatient(draft.notes_for_patient);
      setDraftBanner(`Loaded ${draft.items.length} AI-drafted item${draft.items.length > 1 ? "s" : ""}. Review, edit if needed, then Save prescription.`);
      onDraftConsumed?.();
    }
  }, [draft?.token]);

  const update = (i, key, value) => {
    const next = [...items];
    next[i] = { ...next[i], [key]: value };
    setItems(next);
  };

  const save = async () => {
    setBusy(true); setMsg("");
    try {
      await api.post(`/cases/${caseId}/prescription`, {
        items: items
          .filter((it) => it.medicine_name)
          .map(({ _key, ...it }) => ({ ...it, duration_days: it.duration_days ? Number(it.duration_days) : null })),
        notes_for_patient: notesForPatient,
      });
      setMsg("New prescription version saved.");
      onSaved();
    } catch (e) { setMsg(fmtErr(e)); }
    finally { setBusy(false); }
  };

  return (
    <div className="bg-white border border-gray-200 rounded-md p-4 sm:p-6 space-y-5" data-testid="prescription-tab">
      {draftBanner && (
        <div className="flex items-start gap-2 rounded-md border border-teal-200 bg-teal-50 px-3 py-2.5 text-sm text-teal-900" data-testid="rx-ai-draft-banner">
          <Wand2 size={16} strokeWidth={1.75} className="text-teal-700 mt-0.5 shrink-0" />
          <div className="flex-1">{draftBanner}</div>
          <button onClick={() => setDraftBanner("")} className="text-teal-700 hover:text-teal-900 text-xs font-medium">Dismiss</button>
        </div>
      )}
      {latest && <div className="text-xs text-gray-500" data-testid="current-prescription-version">Current version: <span className="tabular-nums font-medium text-gray-700">v{latest.version_no}</span></div>}
      <div className="space-y-3">
        {items.map((it, i) => (
          <div key={it._key} className="border border-gray-200 rounded-md p-3 space-y-2 sm:space-y-0 sm:grid sm:grid-cols-12 sm:gap-2 sm:items-start" data-testid={`rx-item-${i}`}>
            <input className="input sm:col-span-3" placeholder="Medicine" value={it.medicine_name} onChange={(e) => update(i, "medicine_name", e.target.value)} data-testid={`rx-medicine-${i}`} />
            <input className="input sm:col-span-2" placeholder="Potency (e.g. 30C)" value={it.potency} onChange={(e) => update(i, "potency", e.target.value)} data-testid={`rx-potency-${i}`} />
            <input className="input sm:col-span-2" placeholder="Dosage" value={it.dosage} onChange={(e) => update(i, "dosage", e.target.value)} data-testid={`rx-dosage-${i}`} />
            <input className="input sm:col-span-2" placeholder="Frequency" value={it.frequency} onChange={(e) => update(i, "frequency", e.target.value)} data-testid={`rx-frequency-${i}`} />
            <input className="input sm:col-span-2 tabular-nums" type="number" placeholder="Days" value={it.duration_days} onChange={(e) => update(i, "duration_days", e.target.value)} data-testid={`rx-duration-${i}`} />
            <button
              onClick={() => setItems(items.filter((_, j) => j !== i))}
              className="sm:col-span-1 text-gray-400 hover:text-red-600 py-2 grid place-items-center min-h-[40px] w-full sm:w-auto border sm:border-0 border-gray-200 rounded"
              aria-label="Remove medicine"
              data-testid={`rx-remove-medicine-${i}`}
            >
              <Trash2 size={14} />
            </button>
            <textarea rows={1} className="input sm:col-span-12" placeholder="Instructions (optional)" value={it.instructions} onChange={(e) => update(i, "instructions", e.target.value)} data-testid={`rx-instructions-${i}`} />
          </div>
        ))}
        <button onClick={() => setItems([...items, withKey({ ...EMPTY_ITEM })])} className="inline-flex items-center gap-1 text-sm text-teal-700 hover:text-teal-800 font-medium min-h-[40px]" data-testid="add-rx-item-btn">
          <Plus size={14} /> Add medicine
        </button>
      </div>
      <Field label="Notes for patient (printable)">
        <textarea rows={3} className="input" value={notesForPatient} onChange={(e) => setNotesForPatient(e.target.value)} data-testid="rx-patient-instructions" />
      </Field>
      <div className="flex flex-col sm:flex-row sm:items-center gap-3 pt-1">
        <button onClick={save} disabled={busy} className="inline-flex items-center justify-center gap-2 px-4 py-2.5 bg-teal-700 hover:bg-teal-800 text-white rounded-md text-sm font-medium disabled:opacity-60 min-h-[44px]" data-testid="save-rx-btn">
          {busy ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />} Save prescription
        </button>
        {msg && <span className="text-sm text-gray-500">{msg}</span>}
      </div>
      <style>{`.input { padding:0.625rem 0.75rem; border:1px solid #e5e7eb; border-radius:0.375rem; font-size:0.9375rem; outline:none; width:100%; }
      .input:focus { border-color:#0F766E; box-shadow: 0 0 0 3px rgba(15,118,110,.18); }`}</style>
    </div>
  );
}

function FollowupTab({ caseData, onSaved }) {
  const initialDate = caseData.next_followup_date
    || (caseData.next_followup_at ? caseData.next_followup_at.slice(0, 10) : "");
  const [followupDate, setFollowupDate] = useState(initialDate);
  const [note, setNote] = useState(caseData.followup_note || "");
  const [notifyPharmacy, setNotifyPharmacy] = useState(false);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");

  const save = async () => {
    setBusy(true); setMsg("");
    try {
      await api.post(`/cases/${caseData.id}/followup`, {
        next_followup_date: followupDate,
        followup_note: note,
        notify_pharmacy: notifyPharmacy,
      });
      setMsg(`Follow-up scheduled for ${followupDate}. ${notifyPharmacy ? "Pharmacy notified." : "Reminder added."}`);
      onSaved();
    } catch (e) { setMsg(fmtErr(e)); }
    finally { setBusy(false); }
  };

  return (
    <div className="bg-white border border-gray-200 rounded-md p-4 sm:p-6 space-y-4 max-w-xl" data-testid="followup-tab">
      <Field label="Next follow-up date">
        <input type="date" className="input" value={followupDate} onChange={(e) => setFollowupDate(e.target.value)} data-testid="followup-date" />
      </Field>
      <Field label="Note">
        <textarea rows={3} className="input" value={note} onChange={(e) => setNote(e.target.value)} />
      </Field>
      <label className="flex items-center gap-2 text-sm text-gray-700 min-h-[40px]">
        <input type="checkbox" className="w-4 h-4" checked={notifyPharmacy} onChange={(e) => setNotifyPharmacy(e.target.checked)} data-testid="notify-pharmacy" />
        Also notify pharmacy (will appear on their dashboard until completed)
      </label>
      <button onClick={save} disabled={busy || !followupDate} className="inline-flex items-center justify-center gap-2 px-4 py-2.5 bg-teal-700 hover:bg-teal-800 disabled:opacity-50 text-white rounded-md text-sm font-medium min-h-[44px]" data-testid="save-followup-btn">
        {busy ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />} Save follow-up
      </button>
      {msg && <div className="text-sm text-gray-500">{msg}</div>}
      <style>{`.input { width:100%; padding:0.625rem 0.75rem; border:1px solid #e5e7eb; border-radius:0.375rem; font-size:0.9375rem; outline:none; }
      .input:focus { border-color:#0F766E; box-shadow: 0 0 0 3px rgba(15,118,110,.18); }`}</style>
    </div>
  );
}

function AiTab({ caseId, onApplyDraft }) {
  const [result, setResult] = useState("");
  const [resultKind, setResultKind] = useState("markdown"); // "markdown" | "plain"
  const [busy, setBusy] = useState("");
  const [err, setErr] = useState("");
  const [applyBusy, setApplyBusy] = useState(false);
  const [applyErr, setApplyErr] = useState("");

  const run = async (action) => {
    setBusy(action); setErr(""); setResult(""); setApplyErr("");
    setResultKind(action === "decision_support" ? "markdown" : "plain");
    try {
      const { data } = await api.post(`/cases/${caseId}/ai/${action}`);
      setResult(data.result);
    } catch (e) { setErr(fmtErr(e)); }
    finally { setBusy(""); }
  };

  const applyToRx = async () => {
    if (!result) return;
    setApplyBusy(true); setApplyErr("");
    try {
      const { data } = await api.post(`/cases/${caseId}/ai/apply-to-rx`, { advisory: result });
      if (!data.items?.length) {
        setApplyErr("AI could not extract a concrete prescription from this advisory. Try re-running Analyze Case or add more clinical notes first.");
        return;
      }
      onApplyDraft?.(data.items, data.notes_for_patient || "");
    } catch (e) { setApplyErr(fmtErr(e)); }
    finally { setApplyBusy(false); }
  };

  const quickActions = [
    { key: "summarize",    label: "Summarize complaint",    desc: "Structured assessment draft from complaint." },
    { key: "advice",       label: "Draft patient advice",   desc: "Patient-friendly follow-up advice (uses preferred language)." },
    { key: "instructions", label: "Prescription instructions", desc: "Numbered medication instructions." },
  ];

  return (
    <div className="space-y-4" data-testid="ai-tab">
      {/* Hero: Clinical Decision Support */}
      <div className="rounded-lg border border-teal-200 bg-gradient-to-br from-teal-50 via-emerald-50 to-white p-4 sm:p-6" data-testid="ai-decision-support-card">
