              data-testid={`ai-${a.key}-btn`}
            >
              <div className="flex items-center gap-2 mb-1">
                {busy === a.key ? <Loader2 size={14} className="animate-spin text-teal-700" /> : <Sparkles size={14} strokeWidth={1.5} className="text-teal-700" />}
