import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { api, fmtErr } from "@/lib/api";
import StatusBadge from "@/components/StatusBadge";
import { ArrowLeft, Save, Loader2, Plus, Trash2, ArrowRight } from "lucide-react";

const EMPTY_ITEM = { medicine_name: "", potency: "", dosage: "", frequency: "", duration_days: "", instructions: "" };
const withKey = (it) => ({ ...it, _key: it._key || (typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`) });

export default function PharmacyCase() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [data, setData] = useState(null);
  const [err, setErr] = useState("");
  const [items, setItems] = useState([]);
  const [dispense, setDispense] = useState({ status: "FULL", medicine_amount: 0, patient_purchased_medicines: true, pharmacy_notes: "" });
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");

  const reload = async () => {
    try {
      const { data } = await api.get(`/cases/${id}`);
      setData(data);
      setItems(data.latest_prescription?.items?.length ? data.latest_prescription.items.map(withKey) : [withKey({ ...EMPTY_ITEM })]);
      if (data.pharmacy_dispense) setDispense(data.pharmacy_dispense);
    } catch (e) { setErr(fmtErr(e)); }
  };
  useEffect(() => { reload(); }, [id]);

  if (err) return <div className="p-8 text-red-700">{err}</div>;
  if (!data) return <div className="p-8 grid place-items-center text-gray-400"><Loader2 className="animate-spin" /></div>;

  const c = data.case;

  const update = (i, k, v) => { const next = [...items]; next[i] = { ...next[i], [k]: v }; setItems(next); };

  const savePrescription = async () => {
    setBusy(true); setMsg("");
    try {
      await api.post(`/cases/${c.id}/prescription`, {
        items: items.filter((it) => it.medicine_name).map(({ _key, ...it }) => ({ ...it, duration_days: it.duration_days ? Number(it.duration_days) : null })),
        notes_for_patient: data.latest_prescription?.notes_for_patient || "",
      });
      setMsg("New prescription version saved.");
      reload();
    } catch (e) { setMsg(fmtErr(e)); }
    finally { setBusy(false); }
  };

  const saveDispense = async () => {
    setBusy(true); setMsg("");
    try {
      await api.post(`/cases/${c.id}/dispense`, { ...dispense, medicine_amount: Number(dispense.medicine_amount) || 0 });
      setMsg("Dispense saved. Case marked Completed.");
      reload();
    } catch (e) { setMsg(fmtErr(e)); }
    finally { setBusy(false); }
  };

  return (
    <div className="p-4 sm:p-6 lg:p-8 max-w-6xl mx-auto" data-testid="pharmacy-case">
      <button onClick={() => navigate(-1)} className="inline-flex items-center gap-1 text-sm text-gray-500 hover:text-gray-900 mb-3"><ArrowLeft size={14} /> Back</button>
      <div className="bg-white border border-gray-200 rounded-md p-6 mb-6 flex items-start justify-between">
        <div>
          <div className="text-xs uppercase tracking-wider text-gray-500 font-semibold mb-1 tabular-nums">{c.case_uid}</div>
          <h1 className="font-display text-2xl sm:text-3xl font-semibold tracking-tight text-gray-900">{c.patient?.first_name} {c.patient?.last_name}</h1>
          <div className="text-sm text-gray-600 mt-1 tabular-nums">{c.patient?.patient_uid} · {c.patient?.gender} · {c.patient?.age}y</div>
        </div>
        <StatusBadge status={c.status} />
      </div>

      {/* Prescription editor */}
      <div className="bg-white border border-gray-200 rounded-md p-6 mb-6">
        <div className="flex justify-between items-center mb-4">
          <div>
            <h2 className="font-display text-lg font-semibold text-gray-900">Prescription</h2>
            {data.latest_prescription && <div className="text-xs text-gray-500">Current version: v{data.latest_prescription.version_no}{data.latest_prescription.edited_by_pharmacy ? " (pharmacy edit)" : ""}</div>}
          </div>
        </div>
        <div className="space-y-3">
          {items.map((it, i) => (
            <div key={it._key} className="grid grid-cols-12 gap-2 items-start border border-gray-200 rounded-md p-3">
              <input className="input col-span-3" placeholder="Medicine" value={it.medicine_name} onChange={(e) => update(i, "medicine_name", e.target.value)} />
              <input className="input col-span-2" placeholder="Potency" value={it.potency || ""} onChange={(e) => update(i, "potency", e.target.value)} />
              <input className="input col-span-2" placeholder="Dosage" value={it.dosage || ""} onChange={(e) => update(i, "dosage", e.target.value)} />
              <input className="input col-span-2" placeholder="Frequency" value={it.frequency || ""} onChange={(e) => update(i, "frequency", e.target.value)} />
              <input className="input col-span-2 tabular-nums" type="number" placeholder="Days" value={it.duration_days || ""} onChange={(e) => update(i, "duration_days", e.target.value)} />
              <button onClick={() => setItems(items.filter((_, j) => j !== i))} className="col-span-1 text-gray-400 hover:text-red-600 py-2 grid place-items-center"><Trash2 size={14} /></button>
            </div>
          ))}
          <button onClick={() => setItems([...items, withKey({ ...EMPTY_ITEM })])} className="inline-flex items-center gap-1 text-sm text-teal-700 hover:text-teal-800 font-medium"><Plus size={14} /> Add medicine</button>
        </div>
        <button onClick={savePrescription} disabled={busy} className="mt-4 inline-flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 hover:border-teal-600 text-gray-900 rounded-md text-sm font-medium disabled:opacity-60" data-testid="pharmacy-save-rx-btn">
          {busy ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />} Save prescription edit
        </button>
      </div>

      {/* Dispense */}
      <div className="bg-white border border-gray-200 rounded-md p-6">
        <h2 className="font-display text-lg font-semibold text-gray-900 mb-4">Dispense</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <Field label="Status">
            <select className="input" value={dispense.status} onChange={(e) => setDispense({ ...dispense, status: e.target.value })} data-testid="dispense-status">
              <option value="FULL">Fully dispensed</option>
              <option value="PARTIAL">Partial</option>
              <option value="NOT_DISPENSED">Not dispensed</option>
            </select>
          </Field>
          <Field label="Medicine amount (₹)">
            <input type="number" min={0} step="0.01" className="input tabular-nums" value={dispense.medicine_amount} onChange={(e) => setDispense({ ...dispense, medicine_amount: e.target.value })} data-testid="dispense-amount" />
          </Field>
          <Field label="Patient took medicines?">
            <select className="input" value={dispense.patient_purchased_medicines ? "Y" : "N"} onChange={(e) => setDispense({ ...dispense, patient_purchased_medicines: e.target.value === "Y" })} data-testid="dispense-purchased">
              <option value="Y">Yes</option>
              <option value="N">No</option>
            </select>
          </Field>
          <Field label="Internal notes">
            <input className="input" value={dispense.pharmacy_notes || ""} onChange={(e) => setDispense({ ...dispense, pharmacy_notes: e.target.value })} />
          </Field>
        </div>
        <div className="flex items-center gap-3 mt-5">
          <button onClick={saveDispense} disabled={busy} className="inline-flex items-center gap-2 px-4 py-2 bg-teal-700 hover:bg-teal-800 text-white rounded-md text-sm font-medium disabled:opacity-60" data-testid="save-dispense-btn">
            {busy ? <Loader2 size={14} className="animate-spin" /> : <ArrowRight size={14} />} Dispense & complete case
          </button>
          {msg && <span className="text-sm text-gray-500">{msg}</span>}
        </div>
      </div>
      <style>{`.input { width:100%; padding:0.5rem 0.75rem; border:1px solid #e5e7eb; border-radius:0.375rem; font-size:0.875rem; outline:none; }
      .input:focus { border-color:#0F766E; box-shadow: 0 0 0 3px rgba(15,118,110,.18); }`}</style>
    </div>
  );
}

function Field({ label, children }) {
  return (
    <div>
      <label className="text-xs uppercase tracking-wider font-semibold text-gray-500 block mb-1.5">{label}</label>
      {children}
    </div>
  );
}

import { useEffect, useState, useRef } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { api, fmtErr } from "@/lib/api";
import StatusBadge, { PaymentBadge } from "@/components/StatusBadge";
import { ArrowLeft, Loader2, Save, Printer, CheckCircle2, User, ListChecks, Upload, FileImage, Trash2 } from "lucide-react";
import { PackageBilling } from "@/components/packages/PackageBilling";
import { PackageSummary } from "@/components/packages/PackageSummary";

export default function BillingDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [data, setData] = useState(null);
  const [err, setErr] = useState("");
  const [form, setForm] = useState({
    consultation_amount: 500,
    medicines_taken: true,
    medicine_amount: 0,
    amount_paid: 0,
    payment_mode: "CASH",
  });
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");
  const [billingMode, setBillingMode] = useState("legacy");

  const reload = async () => {
    try {
      const { data } = await api.get(`/cases/${id}`);
      setData(data);
      if (data.payment) {
        setForm({
          consultation_amount: data.payment.consultation_amount,
          medicines_taken: data.payment.medicines_taken,
          medicine_amount: data.payment.medicine_amount,
          amount_paid: data.payment.amount_paid,
          payment_mode: data.payment.payment_mode || "CASH",
        });
      } else if (data.pharmacy_dispense?.medicine_amount) {
        setForm((f) => ({
          ...f,
          medicine_amount: data.pharmacy_dispense.medicine_amount,
          medicines_taken: data.pharmacy_dispense.patient_purchased_medicines,
        }));
      }
    } catch (e) { setErr(fmtErr(e)); }
  };
  useEffect(() => { reload(); }, [id]);

  if (err) return <div className="p-8 text-red-700">{err}</div>;
  if (!data) return <div className="p-8 grid place-items-center text-gray-400"><Loader2 className="animate-spin" /></div>;

  const c = data.case;
  const packageMode = !!c.package_id || billingMode === "package";
  const total = Number(form.consultation_amount || 0) + (form.medicines_taken ? Number(form.medicine_amount || 0) : 0);
  const balance = Math.max(0, total - Number(form.amount_paid || 0));
  const isClosed = c.status === "CLOSED" && data.payment?.payment_status === "PAID";
  const wasSentToPharmacy = c.status === "SENT_TO_PHARMACY" || c.status === "IN_PHARMACY";
  const canSendToPharmacy = ["AWAITING_PRO_REVIEW", "PAYMENT_PENDING", "PARTIALLY_PAID"].includes(c.status);

  const save = async () => {
    setBusy(true); setMsg("");
    try {
      await api.post(`/cases/${c.id}/payment`, {
        consultation_amount: Number(form.consultation_amount) || 0,
        medicines_taken: !!form.medicines_taken,
        medicine_amount: Number(form.medicine_amount) || 0,
        amount_paid: Number(form.amount_paid) || 0,
        payment_mode: form.payment_mode,
      });
      setMsg("Payment recorded.");
      reload();
    } catch (e) { setMsg(fmtErr(e)); }
    finally { setBusy(false); }
  };

  const sendToPharmacyNow = async () => {
    if (!window.confirm("Forward this case to Pharmacy now? Use this when payment is partial or pending but the patient should still receive medicines.")) return;
    try {
      await api.patch(`/cases/${c.id}/status`, { status: "SENT_TO_PHARMACY" });
      setMsg("Case forwarded to Pharmacy.");
      reload();
    } catch (e) { setMsg(fmtErr(e)); }
  };

  return (
    <div className="p-4 sm:p-6 lg:p-8 max-w-5xl mx-auto" data-testid="billing-detail">
      <button onClick={() => navigate(-1)} className="inline-flex items-center gap-1 text-sm text-gray-500 hover:text-gray-900 mb-3"><ArrowLeft size={14} /> Back</button>
      <div className="bg-white border border-gray-200 rounded-md p-4 sm:p-6 mb-6 flex flex-wrap items-start justify-between gap-4">
        <div>
          <div className="text-xs uppercase tracking-wider text-gray-500 font-semibold mb-1 tabular-nums">{c.case_uid}</div>
          <h1 className="font-display text-2xl sm:text-3xl font-semibold tracking-tight text-gray-900">{c.patient?.first_name} {c.patient?.last_name}</h1>
          <div className="text-sm text-gray-600 mt-1 tabular-nums">{c.patient?.patient_uid} · {c.patient?.phone} · Doctor: {c.doctor?.display_name}</div>
          {c.package_snapshot && <div className="mt-4"><PackageSummary value={c.package_snapshot} prefix="billing-package-snapshot" compact /></div>}
        </div>
        <div className="flex flex-col items-end gap-2">
          <StatusBadge status={c.status} />
          {data.payment && <PaymentBadge status={data.payment.payment_status} />}
        </div>
      </div>

      {!data.payment && !c.package_id && <div className="flex flex-wrap gap-2 mb-5" role="group" aria-label="Billing type"><button onClick={() => setBillingMode("legacy")} className={`px-4 py-2 text-sm border rounded-md ${!packageMode ? "bg-teal-700 text-white" : "bg-white"}`} data-testid="billing-mode-visit">Per-visit billing</button><button onClick={() => setBillingMode("package")} className={`px-4 py-2 text-sm border rounded-md ${packageMode ? "bg-teal-700 text-white" : "bg-white"}`} data-testid="billing-mode-package">Package billing</button></div>}
      {packageMode && <PackageBilling key={c.package_id || c.id} caseData={c} onSaved={reload} />}
      {isClosed && !packageMode && (
        <div className="bg-gradient-to-br from-emerald-50 to-white border-2 border-emerald-200 rounded-md p-6 mb-6" data-testid="payment-success-card">
          <div className="flex items-start gap-4">
            <div className="w-12 h-12 rounded-full bg-emerald-100 text-emerald-700 grid place-items-center shrink-0">
              <CheckCircle2 size={24} strokeWidth={1.75} />
            </div>
            <div className="flex-1">
              <h2 className="font-display text-xl font-semibold text-emerald-900 tracking-tight">Payment received · Case closed</h2>
              <p className="text-sm text-emerald-800 mt-1">
                Receipt <span className="font-mono font-semibold tabular-nums">{data.payment.receipt_no}</span> · ₹{Number(data.payment.amount_paid).toFixed(0)} via <span className="font-medium">{data.payment.payment_mode || "—"}</span>.
                The case is now in the closed archive.
              </p>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mt-4 text-xs">
                <div className="bg-white border border-emerald-100 rounded p-2.5">
                  <div className="text-emerald-700 uppercase tracking-wider font-semibold text-[10px] mb-0.5">Consultation</div>
                  <div className="tabular-nums font-semibold text-gray-900">₹{Number(data.payment.consultation_amount).toFixed(2)}</div>
                </div>
                <div className="bg-white border border-emerald-100 rounded p-2.5">
                  <div className="text-emerald-700 uppercase tracking-wider font-semibold text-[10px] mb-0.5">Medicines</div>
                  <div className="tabular-nums font-semibold text-gray-900">₹{Number(data.payment.medicine_amount).toFixed(2)}</div>
                </div>
                <div className="bg-white border border-emerald-100 rounded p-2.5">
                  <div className="text-emerald-700 uppercase tracking-wider font-semibold text-[10px] mb-0.5">Total</div>
                  <div className="tabular-nums font-semibold text-gray-900">₹{Number(data.payment.total_amount).toFixed(2)}</div>
                </div>
              </div>
              <div className="flex gap-2 mt-5">
                <Link to={`/pro/cases/${c.id}/receipt`} target="_blank" className="inline-flex items-center gap-2 px-3.5 py-2 bg-emerald-700 hover:bg-emerald-800 text-white rounded-md text-sm font-medium" data-testid="success-print-btn">
                  <Printer size={14} strokeWidth={1.5} /> Print receipt
                </Link>
                {c.patient?.id && (
                  <Link to={`/reception/patients/${c.patient.id}/timeline`} className="inline-flex items-center gap-2 px-3.5 py-2 bg-white border border-gray-200 hover:border-emerald-600 rounded-md text-sm font-medium" data-testid="success-timeline-btn">
                    <User size={14} strokeWidth={1.5} /> Patient timeline
                  </Link>
                )}
                <Link to="/pro" className="inline-flex items-center gap-2 px-3.5 py-2 bg-white border border-gray-200 hover:border-emerald-600 rounded-md text-sm font-medium" data-testid="success-queue-btn">
                  <ListChecks size={14} strokeWidth={1.5} /> Back to billing queue
                </Link>
              </div>
            </div>
          </div>
        </div>
      )}

      {!packageMode && <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
        <div className={`sm:col-span-2 min-w-0 bg-white border border-gray-200 rounded-md p-4 sm:p-6 ${isClosed ? "opacity-75" : ""}`}>
          <h2 className="font-display text-lg font-semibold text-gray-900 mb-4">
            {isClosed ? "Payment summary (closed)" : "Payment"}
          </h2>
          <fieldset disabled={isClosed} className="space-y-4 disabled:cursor-not-allowed">
            <Field label="Consultation amount (₹)">
              <input type="number" className="input tabular-nums" value={form.consultation_amount} onChange={(e) => setForm({ ...form, consultation_amount: e.target.value })} data-testid="consult-amount" />
              <div className="flex gap-2 mt-2">
                {[300, 500, 700, 1000].map((v) => (
                  <button key={v} type="button" onClick={() => setForm({ ...form, consultation_amount: v })} className="text-xs px-2 py-1 border border-gray-200 rounded hover:border-teal-600 tabular-nums">₹{v}</button>
                ))}
              </div>
            </Field>
            <Field label="Patient took medicines?">
              <select className="input" value={form.medicines_taken ? "Y" : "N"} onChange={(e) => setForm({ ...form, medicines_taken: e.target.value === "Y" })} data-testid="medicines-taken">
                <option value="Y">Yes</option>
                <option value="N">No (consultation only)</option>
              </select>
            </Field>
            {form.medicines_taken && (
              <Field label="Medicine amount (₹)">
                <input type="number" className="input tabular-nums" value={form.medicine_amount} onChange={(e) => setForm({ ...form, medicine_amount: e.target.value })} data-testid="medicine-amount" />
              </Field>
            )}
            <Field label="Amount paid (₹)">
              <input type="number" className="input tabular-nums" value={form.amount_paid} onChange={(e) => setForm({ ...form, amount_paid: e.target.value })} data-testid="amount-paid" />
              <button type="button" onClick={() => setForm((f) => ({ ...f, amount_paid: total }))} className="text-xs text-teal-700 hover:text-teal-800 mt-1">Pay total ₹{total}</button>
            </Field>
            <Field label="Payment mode">
              <div className="grid grid-cols-2 lg:grid-cols-4 gap-2">
                {["CASH", "PHONEPE", "CARD", "OTHER"].map((m) => (
                  <button key={m} type="button" onClick={() => setForm({ ...form, payment_mode: m })} className={`px-3 py-2 rounded-md text-sm font-medium border ${form.payment_mode === m ? "bg-teal-700 text-white border-teal-700" : "bg-white border-gray-200 text-gray-700 hover:border-teal-600"}`} data-testid={`mode-${m}`}>
                    {m}
                  </button>
                ))}
              </div>
            </Field>

            <div className="flex items-center gap-3 pt-2 flex-wrap">
              <button onClick={save} disabled={busy || isClosed} className="inline-flex items-center gap-2 px-4 py-2 bg-teal-700 hover:bg-teal-800 text-white rounded-md text-sm font-medium disabled:opacity-60" data-testid="save-payment-btn">
                {busy ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />} {isClosed ? "Already recorded" : "Record payment"}
              </button>
              {canSendToPharmacy && form.medicines_taken && (
                <button onClick={sendToPharmacyNow} className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-md text-sm font-medium" data-testid="send-to-pharmacy-btn" title="Forward case to Pharmacy now (manual override)">
                  Send to Pharmacy
                </button>
              )}
              {wasSentToPharmacy && (
                <span className="text-xs text-indigo-700 bg-indigo-50 border border-indigo-200 rounded px-2.5 py-1.5 font-medium" data-testid="sent-to-pharmacy-badge">Forwarded to Pharmacy</span>
              )}
              {data.payment && !isClosed && (
                <Link to={`/pro/cases/${c.id}/receipt`} target="_blank" className="inline-flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 hover:border-teal-600 rounded-md text-sm font-medium" data-testid="print-receipt-btn">
                  <Printer size={14} /> Print receipt
                </Link>
              )}
              {msg && <span className="text-sm text-gray-500">{msg}</span>}
            </div>
          </fieldset>
        </div>

        <div className="col-span-1 bg-white border border-gray-200 rounded-md p-6 h-fit">
          <h3 className="font-display text-sm font-semibold text-gray-900 mb-4">Summary</h3>
          <Row label="Consultation" value={Number(form.consultation_amount) || 0} />
          {form.medicines_taken && <Row label="Medicines" value={Number(form.medicine_amount) || 0} />}
          <div className="border-t border-gray-200 my-3" />
          <Row label="Total" value={total} bold />
          <Row label="Paid" value={Number(form.amount_paid) || 0} />
          <Row label="Balance" value={balance} bold />
        </div>
      </div>}

      <PaymentProofPanel caseId={c.id} />
      <style>{`.input { width:100%; padding:0.5rem 0.75rem; border:1px solid #e5e7eb; border-radius:0.375rem; font-size:0.875rem; outline:none; }
      .input:focus { border-color:#0F766E; box-shadow: 0 0 0 3px rgba(15,118,110,.18); }`}</style>
    </div>
  );
}

function PaymentProofPanel({ caseId }) {
  const [proofs, setProofs] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [err, setErr] = useState("");
  const inputRef = useRef(null);

  const load = async () => {
    try {
      const { data } = await api.get(`/cases/${caseId}/attachments?kind=PAYMENT_PROOF`);
      setProofs(data.attachments || []);
    } catch (e) { setErr(fmtErr(e)); }
  };
  useEffect(() => { load(); }, [caseId]);

  const onFile = async (e) => {
    const f = e.target.files?.[0];
    if (!f) return;
    setUploading(true); setErr("");
    try {
      const fd = new FormData();
      fd.append("file", f);
      fd.append("kind", "PAYMENT_PROOF");
      await api.post(`/cases/${caseId}/attachments`, fd, { headers: { "Content-Type": "multipart/form-data" } });
      await load();
    } catch (e2) { setErr(fmtErr(e2)); }
    finally {
      setUploading(false);
      if (inputRef.current) inputRef.current.value = "";
    }
  };

  const remove = async (a) => {
    if (!window.confirm("Remove this payment proof?")) return;
    try { await api.delete(`/attachments/${a.id}`); load(); }
    catch (e) { setErr(fmtErr(e)); }
  };

  return (
    <div className="bg-white border border-gray-200 rounded-md p-6 mt-6" data-testid="payment-proof-panel">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h3 className="font-display text-sm font-semibold text-gray-900">Payment proof <span className="text-gray-400 font-normal">(optional)</span></h3>
          <p className="text-xs text-gray-500 mt-0.5">Upload a screenshot of the UPI / PhonePe / GPay confirmation. Stored against this case.</p>
        </div>
        <label className="inline-flex items-center gap-2 px-3 py-2 bg-white border border-gray-200 hover:border-teal-600 rounded-md text-sm font-medium cursor-pointer" data-testid="upload-proof-btn">
          {uploading ? <Loader2 size={14} className="animate-spin" /> : <Upload size={14} />}
          Upload proof
          <input ref={inputRef} type="file" accept="image/*,.pdf" onChange={onFile} className="hidden" disabled={uploading} data-testid="proof-file-input" />
        </label>
      </div>
      {err && <div className="text-sm text-red-700 bg-red-50 border border-red-200 rounded-md px-3 py-2 mb-3">{err}</div>}
      {proofs.length === 0 ? (
        <div className="text-sm text-gray-400 py-4">No payment proof uploaded yet.</div>
      ) : (
        <ul className="divide-y divide-gray-100" data-testid="proof-list">
          {proofs.map((p) => (
            <li key={p.id} className="flex items-center justify-between py-2.5" data-testid={`proof-${p.id}`}>
              <div className="flex items-center gap-3 min-w-0">
                <div className="w-8 h-8 rounded bg-teal-50 text-teal-700 grid place-items-center shrink-0"><FileImage size={14} /></div>
                <div className="min-w-0">
                  <div className="text-sm text-gray-900 truncate">{p.original_filename}</div>
                  <div className="text-[11px] text-gray-500 tabular-nums">{new Date(p.created_at).toLocaleString()} · {(p.size_bytes / 1024).toFixed(0)} KB · by {p.uploaded_by_name || "—"}</div>
                </div>
              </div>
              <div className="flex gap-1">
                <a href={`${process.env.REACT_APP_BACKEND_URL}/api/attachments/${p.id}/download`} target="_blank" rel="noreferrer" className="text-xs px-2.5 py-1.5 border border-gray-200 rounded hover:border-teal-600 hover:text-teal-700">View</a>
                <button onClick={() => remove(p)} className="text-xs px-2.5 py-1.5 border border-gray-200 rounded hover:border-red-500 hover:text-red-600 inline-flex items-center gap-1" data-testid={`del-proof-${p.id}`}><Trash2 size={12} /></button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function Field({ label, children }) {
  return (
    <div>
      <label className="text-xs uppercase tracking-wider font-semibold text-gray-500 block mb-1.5">{label}</label>
      {children}
    </div>
  );
}

function Row({ label, value, bold }) {
  return (
    <div className={`flex justify-between py-1.5 text-sm ${bold ? "font-semibold text-gray-900" : "text-gray-600"}`}>
      <span>{label}</span>
      <span className="tabular-nums">₹{Number(value).toFixed(2)}</span>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { api, fmtErr } from "@/lib/api";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { ArrowLeft, RotateCcw, CalendarPlus, Check, Loader2 } from "lucide-react";
import { PackageSummary, PackageStatus, money, dateLabel, today, label } from "@/components/packages/PackageSummary";
import { PackagePaymentForm } from "@/components/packages/PackagePaymentForm";
import { PackageForm } from "@/components/packages/PackageForm";
import { PackageLedger } from "@/components/packages/PackageLedger";

export default function PackageDetail() {
  const { id } = useParams(), { user } = useAuth(), navigate = useNavigate();
  const [data, setData] = useState(null), [error, setError] = useState(""), [renewing, setRenewing] = useState(false), [busy, setBusy] = useState(false);
  const [followup, setFollowup] = useState({ scheduled_date: today(), message: "Package follow-up" });
  const [reversal, setReversal] = useState(null), [reason, setReason] = useState("");
  const privileged = ["ADMIN", "OWNER_DOCTOR"].includes(user?.role);
  const readOnly = user?.role === "DOCTOR";
  const load = async () => { const r = await api.get(`/packages/${id}`); setData(r.data); };
  useEffect(() => { setData(null); setError(""); setRenewing(false); load().catch(e => setError(fmtErr(e))); }, [id]);
  const action = async (path, body) => { setBusy(true); setError(""); try { await api.post(path, body); await load(); return true; } catch (e) { setError(fmtErr(e)); return false; } finally { setBusy(false); } };
  if (!data) return <div className="p-6" data-testid="package-detail-loading">{error || <Loader2 className="animate-spin" />}</div>;
  const p = data.package;
  return <div className="p-4 sm:p-6 lg:p-8 max-w-6xl mx-auto space-y-6" data-testid="package-detail-page">
    <Link to="/pro/packages" className="inline-flex items-center gap-1 text-sm text-gray-500" data-testid="back-to-packages"><ArrowLeft size={15} />Packages & dues</Link>
    <header><p className="text-xs text-gray-500" data-testid="package-detail-patient-uid">{data.patient?.patient_uid}</p><h1 className="font-display text-2xl sm:text-3xl font-semibold break-words" data-testid="package-detail-patient-name">{data.patient?.first_name} {data.patient?.last_name}</h1><a href={`tel:${data.patient?.phone}`} className="text-sm text-teal-700" data-testid="package-call-patient">{data.patient?.phone}</a></header>
    <PackageSummary value={p} />
    {error && <p role="alert" className="text-red-700 text-sm" data-testid="package-detail-error">{error}</p>}
    {!readOnly && <div className="grid lg:grid-cols-2 gap-x-10 gap-y-6">
      <section><PackagePaymentForm key={p.id} value={p} onSaved={load} /><div className="border-t border-gray-200 py-5"><h2 className="font-display font-semibold text-base mb-3">Renewal</h2><p className="text-sm text-gray-600 mb-3" data-testid="package-renewal-eligibility">{p.renewal_eligible ? `Eligible from ${dateLabel(p.end_date)}` : p.renewal_status === "REQUIRES_FOLLOWUP" ? `Requires follow-up · Outstanding ${money(p.outstanding)}` : p.package_status === "RENEWED" ? "Renewed · Previous terms and payments retained" : `Renewal date: ${dateLabel(p.end_date)}`}</p><div className="flex flex-wrap gap-2"><Button variant="outline" disabled={!p.renewal_eligible || busy} onClick={() => setRenewing(true)} data-testid="renew-package-button"><RotateCcw size={15} />Renew package</Button>{privileged && p.lifecycle === "OPEN" && p.outstanding === 0 && <Button variant="outline" disabled={busy} onClick={() => { const why = window.prompt("Reason for completing this package (at least 5 characters)"); if (why) action(`/packages/${id}/complete`, { reason: why }); }} data-testid="complete-package-button"><Check size={15} />Mark completed</Button>}</div></div></section>
      <section className="py-5"><h2 className="font-display text-base font-semibold mb-4">PRO follow-up</h2><form onSubmit={async e => { e.preventDefault(); await action(`/packages/${id}/followups`, followup); }} className="space-y-3" data-testid="package-followup-form"><label className="text-sm block">Next follow-up<Input required type="date" min={today()} value={followup.scheduled_date} onChange={e => setFollowup(f => ({ ...f, scheduled_date: e.target.value }))} className="mt-2" data-testid="package-followup-date" /></label><label className="text-sm block">Follow-up note<Textarea required maxLength={1000} value={followup.message} onChange={e => setFollowup(f => ({ ...f, message: e.target.value }))} className="mt-2" data-testid="package-followup-note" /></label><Button disabled={busy} variant="outline" data-testid="save-package-followup"><CalendarPlus size={15} />Schedule follow-up</Button></form><div className="divide-y mt-4">{data.followups.map(r => <div key={r.id} className="py-3 flex gap-3 justify-between items-start" data-testid={`package-followup-${r.id}`}><div className="text-sm min-w-0"><strong>{dateLabel(r.scheduled_date)}</strong><p className="break-words text-gray-600">{r.message}</p><span className="text-xs text-gray-500">{label(r.status)}</span></div>{r.status === "PENDING" && <Button variant="ghost" disabled={busy} onClick={() => action(`/packages/${id}/followups/${r.id}/complete`)} data-testid={`complete-package-followup-${r.id}`}><Check size={15} />Complete</Button>}</div>)}</div></section>
    </div>}
    {renewing && !readOnly && <PackageForm patientId={p.patient_id} previous={p} onCancel={() => setRenewing(false)} onSaved={next => { setRenewing(false); navigate(`/pro/packages/${next.id}`); }} />}
    {reversal && <form className="bg-rose-50 border border-rose-200 p-4 rounded-md space-y-3" data-testid="reversal-form" onSubmit={async e => { e.preventDefault(); if (await action(`/packages/${id}/payments/${reversal.id}/reverse`, { reason, idempotency_key: reversal.requestKey })) setReversal(null); }}><h2 className="text-base font-semibold">Reverse {reversal.receipt_no} · {money(reversal.amount)}</h2><Textarea required minLength={5} maxLength={500} value={reason} onChange={e => setReason(e.target.value)} placeholder="Reason for reversal" data-testid="reversal-reason" /><div className="flex gap-2"><Button disabled={busy} variant="destructive" data-testid="confirm-reversal">Confirm reversal</Button><Button type="button" variant="outline" onClick={() => setReversal(null)} data-testid="cancel-reversal">Cancel</Button></div></form>}
    <PackageLedger value={p} canReverse={privileged} readOnly={readOnly} onReverse={t => { setReason(""); setReversal({ ...t, requestKey: crypto.randomUUID() }); }} />
    <section className="border-t border-gray-200 py-5"><h2 className="font-display text-base font-semibold mb-3">Visits / bills</h2>{data.bills.length === 0 && <p className="text-sm text-gray-500" data-testid="package-bills-empty">No visits linked yet.</p>}<div className="divide-y">{data.bills.map(b => { const paid = p.transactions.filter(t => t.case_id === b.case_id).reduce((sum, t) => sum + t.amount, 0); return <div key={b.case_id} className="flex flex-wrap gap-3 justify-between py-3 text-sm" data-testid={`package-bill-${b.case_id}`}><span>{b.receipt_no} · {dateLabel(b.created_at)}</span><span data-testid={`package-visit-paid-${b.case_id}`}>{money(paid)} {paid === 0 ? "· No payment" : ""}</span>{!readOnly && <Link to={`/pro/cases/${b.case_id}`} className="text-teal-700" data-testid={`package-visit-link-${b.case_id}`}>Open visit</Link>}</div>; })}</div></section>
    <section className="border-t border-gray-200 py-5"><h2 className="font-display text-base font-semibold mb-4">Treatment package history</h2><div className="space-y-3">{data.history.map(h => <div key={h.id} className="border-l-2 border-teal-200 pl-4 py-2 flex flex-wrap gap-3 justify-between" data-testid={`package-history-${h.id}`}><div className="text-sm"><Link to={`/pro/packages/${h.id}`} className="font-medium text-teal-800" data-testid={`package-history-link-${h.id}`}>{h.package_uid} · {h.name}</Link><div className="text-gray-500 mt-1">{dateLabel(h.start_date)} → {dateLabel(h.end_date)} · {h.duration_label}</div><div className="mt-1" data-testid={`package-history-balance-${h.id}`}>{money(h.amount)} · Paid {money(h.total_paid)} · Outstanding {money(h.outstanding)}</div>{h.previous_package_id && <div className="text-xs text-gray-500">Renewed from {data.history.find(x => x.id === h.previous_package_id)?.package_uid}</div>}</div><PackageStatus value={h.package_status} testId={`package-history-status-${h.id}`} /></div>)}</div></section>
  </div>;
}
